  1	/**
  2	 * Settings View — Repo Parallelizer GUI.
  3	 *
  4	 * Renders four settings sections:
  5	 *   1. **Git Credentials** — table of per-host PATs with add/delete controls.
  6	 *   2. **Repositories Refresh Delay** — number input for `gitPollingIntervalSeconds`
  7	 *      with client-side validation (min 10) and save/feedback.
  8	 *   3. **Webserver URL** — text input for the base URL of the local webserver
  9	 *      that serves the workspace repositories, enabling the "Browse" button in
 10	 *      the workspace-detail view.
 11	 *   4. **Notes Display** — number inputs for card height (px) and column count
 12	 *      with client-side range validation and save/feedback.
 13	 *
 14	 * This view has no side-effects (no polling), so it returns no cleanup function.
 15	 *
 16	 * @param {HTMLElement} container - The `#app` root element supplied by the router.
 17	 * @param {Object}      _params   - Route params (none for this route).
 18	 */
 19	
 20	import { api } from '../api.js';
 21	import { showToast } from '../components/toast.js';
 22	import { showConfirm } from '../components/confirm-dialog.js';
 23	import { APP_NAME_SHORT } from '../utils/constants.js';
 24	import { createFormField, validateRequired } from '../components/form-helpers.js';
 25	import { clearElement } from '../utils/dom.js';
 26	
 27	// ---------------------------------------------------------------------------
 28	// Table rendering
 29	// ---------------------------------------------------------------------------
 30	
 31	/**
 32	 * Build the `<thead>` for the credentials table.
 33	 *
 34	 * @returns {HTMLElement}
 35	 */
 36	function buildTableHead() {
 37	    const thead = document.createElement('thead');
 38	    const tr = document.createElement('tr');
 39	
 40	    ['Host', 'Token', 'Actions'].forEach((label) => {
 41	        const th = document.createElement('th');
 42	        th.textContent = label;
 43	        tr.appendChild(th);
 44	    });
 45	
 46	    thead.appendChild(tr);
 47	    return thead;
 48	}
 49	
 50	/**
 51	 * Build a single `<tr>` for one credential entry.
 52	 *
 53	 * @param {string}            host       - The hostname key.
 54	 * @param {string}            maskedToken - The masked token string (e.g. `****abc1`).
 55	 * @param {function(): void}  onDeleted  - Callback to refresh the table after deletion.
 56	 * @returns {HTMLTableRowElement}
 57	 */
 58	function buildCredentialRow(host, maskedToken, onDeleted) {
 59	    const tr = document.createElement('tr');
 60	    tr.dataset.credHost = host;
 61	
 62	    // ---- Host cell (read-only) ----
 63	    const hostCell = document.createElement('td');
 64	    hostCell.className = 'cred-host-cell';
 65	    hostCell.textContent = host;
 66	    tr.appendChild(hostCell);
 67	
 68	    // ---- Masked token cell (read-only) ----
 69	    const tokenCell = document.createElement('td');
 70	    tokenCell.className = 'cred-token-cell text-muted';
 71	    tokenCell.textContent = maskedToken;
 72	    tr.appendChild(tokenCell);
 73	
 74	    // ---- Actions cell ----
 75	    const actionsCell = document.createElement('td');
 76	    actionsCell.className = 'cred-actions-cell';
 77	
 78	    const deleteBtn = document.createElement('button');
 79	    deleteBtn.type = 'button';
 80	    deleteBtn.className = 'btn btn-danger btn-sm';
 81	    deleteBtn.textContent = 'Delete';
 82	
 83	    actionsCell.appendChild(deleteBtn);
 84	    tr.appendChild(actionsCell);
 85	
 86	    // ---- Behaviour ----
 87	
 88	    deleteBtn.addEventListener('click', async () => {
 89	        try {
 90	            await showConfirm(
 91	                'Delete Credential',
 92	                `Remove the credential for "${host}"? This action cannot be undone.`,
 93	            );
 94	        } catch {
 95	            // User cancelled — do nothing.
 96	            return;
 97	        }
 98	
 99	        deleteBtn.disabled = true;
100	        deleteBtn.textContent = 'Deleting…';

101	 *
102	 * @returns {Promise<HTMLElement>} The container element.
103	 */
104	async function renderAndWait() {
105	    const container = document.createElement('div');
106	    container.id = 'app';
107	    document.body.appendChild(container);
108	    renderSettings(container, {});
109	    // Flush micro-tasks and timers to allow async table load to complete.
110	    await new Promise((resolve) => setTimeout(resolve, 0));
111	    return container;
112	}
113	
114	/**
115	 * Remove all rendered containers after each test to avoid DOM leakage.
116	 */
117	function cleanupContainers() {
118	    document.body.querySelectorAll('#app').forEach((el) => el.remove());
119	}
120	
121	// ---------------------------------------------------------------------------
122	// Tests
123	// ---------------------------------------------------------------------------
124	
125	// AC1 + AC2 — buildCredentialsSection() factory and renderSettings() integration
126	// ---------------------------------------------------------------------------
127	
128	test('AC1 — renderSettings() appends a credentials section element', async () => {
129	    const container = await renderAndWait();
130	    try {
131	        const sections = container.querySelectorAll('section.settings-section');
132	        assert.ok(sections.length > 0, 'Should render at least one settings-section');
133	
134	        // The credentials section is the first section under the <h1> heading.
135	        const credSection = sections[0];
136	        assert.ok(credSection, 'Credentials section should exist as the first section');
137	
138	        const heading = credSection.querySelector('h2');
139	        assert.ok(heading, 'Credentials section should have an <h2>');
140	        assert.strictEqual(heading.textContent, 'Git Credentials', 'Heading should read "Git Credentials"');
141	    } finally {
142	        cleanupContainers();
143	    }
144	});
145	
146	test('AC2 — renderSettings() contains no inline credentials section construction', async () => {
147	    // We verify this structurally: calling renderSettings() twice in the same
148	    // container must produce exactly one credentials section (idempotent via
149	    // clearElement). If credentials were constructed inline AND via the factory,
150	    // two sections would appear.
151	    const container = document.createElement('div');
152	    container.id = 'app';
153	    document.body.appendChild(container);
154	    try {
155	        renderSettings(container, {});
156	        await new Promise((resolve) => setTimeout(resolve, 0));
157	
158	        const credSections = Array.from(container.querySelectorAll('section.settings-section h2'))
159	            .filter((h) => h.textContent === 'Git Credentials');
160	
161	        assert.strictEqual(credSections.length, 1, 'Exactly one "Git Credentials" section should be present');
162	    } finally {
163	        cleanupContainers();
164	    }
165	});
166	
167	// AC3 — DOM structure preserved
168	// ---------------------------------------------------------------------------
169	
170	test('AC3 — Credentials table container is present in the credentials section', async () => {
171	    const container = await renderAndWait();
172	    try {
173	        const tableContainer = container.querySelector('.credentials-table-container');
174	        assert.ok(tableContainer, '.credentials-table-container should exist inside the credentials section');
175	    } finally {
176	        cleanupContainers();
177	    }
178	});
179	
180	test('AC3 — Credentials table renders rows for each credential after async load', async () => {
181	    const container = await renderAndWait();
182	    try {
183	        const table = container.querySelector('table.credentials-table');
184	        assert.ok(table, 'credentials-table should be rendered');
185	
186	        const rows = table.querySelectorAll('tbody tr');
187	        assert.strictEqual(
188	            rows.length,
189	            Object.keys(DEFAULT_CREDENTIALS).length,
190	            'Should render one row per credential',
191	        );
192	
193	        // Verify that both known hosts appear in the table.
194	        const hosts = Array.from(rows).map((tr) => {
195	            const cell = tr.querySelector('td.cred-host-cell');
196	            return cell ? cell.textContent : null;
197	        });
198	        assert.ok(hosts.includes('github.com'),  'github.com row should be present');
199	        assert.ok(hosts.includes('gitlab.com'),  'gitlab.com row should be present');
200	    } finally {
201	        cleanupContainers();
202	    }
203	});
204	
205	test('AC3 — Credentials table has correct column headers', async () => {
206	    const container = await renderAndWait();
207	    try {
208	        const thead = container.querySelector('table.credentials-table thead');
209	        assert.ok(thead, 'Table should have a <thead>');
210	
211	        const headers = Array.from(thead.querySelectorAll('th')).map((th) => th.textContent);
212	        assert.deepEqual(headers, ['Host', 'Token', 'Actions'], 'Column headers should match');
213	    } finally {
214	        cleanupContainers();
215	    }
216	});
217	
218	test('AC3 — Masked token is displayed in the token cell', async () => {
219	    const container = await renderAndWait();
220	    try {
221	        const rows = container.querySelectorAll('table.credentials-table tbody tr');
222	        assert.ok(rows.length > 0, 'There should be at least one row');
223	
224	        const firstRow  = rows[0];
225	        const tokenCell = firstRow.querySelector('td.cred-token-cell');
226	        assert.ok(tokenCell, 'Token cell should exist');
227	        assert.match(tokenCell.textContent, /^\*{4}/, 'Token cell should show the masked token');
228	    } finally {
229	        cleanupContainers();
230	    }
231	});
232	
233	test('AC3 — Each credential row has a Delete button', async () => {
234	    const container = await renderAndWait();
235	    try {
236	        const rows = container.querySelectorAll('table.credentials-table tbody tr');
237	        for (const row of rows) {
238	            const deleteBtn = row.querySelector('td.cred-actions-cell button.btn-danger');
239	            assert.ok(deleteBtn, `Row for "${row.dataset.credHost}" should have a Delete button`);
240	            assert.strictEqual(deleteBtn.textContent, 'Delete');
241	        }
242	    } finally {
243	        cleanupContainers();
244	    }
245	});
246	
247	test('AC3 — Add / Update Credential toggle button is present', async () => {
248	    const container = await renderAndWait();
249	    try {
250	        const addSection = container.querySelector('.add-credential-section');
251	        assert.ok(addSection, '.add-credential-section should exist');
252	
253	        const toggleBtn = addSection.querySelector('button.btn-primary');
254	        assert.ok(toggleBtn, 'Toggle button should exist inside add-credential-section');
255	        assert.strictEqual(toggleBtn.textContent, 'Add / Update Credential');
256	    } finally {
257	        cleanupContainers();
258	    }
259	});
260	
261	test('AC3 — Add / Update Credential form is hidden by default', async () => {
262	    const container = await renderAndWait();
263	    try {
264	        const formWrapper = container.querySelector('.add-credential-section .form-wrapper');
265	        assert.ok(formWrapper, 'Form wrapper should exist');
266	        assert.strictEqual(formWrapper.hidden, true, 'Form wrapper should be hidden initially');
267	    } finally {
268	        cleanupContainers();
269	    }
270	});
271	
272	test('AC3 — Clicking the toggle button reveals the Add / Update Credential form', async () => {
273	    const container = await renderAndWait();
274	    try {
275	        const addSection  = container.querySelector('.add-credential-section');
276	        const toggleBtn   = addSection.querySelector('button.btn-primary');
277	        const formWrapper = addSection.querySelector('.form-wrapper');
278	
279	        assert.strictEqual(formWrapper.hidden, true, 'Form wrapper should start hidden');
280	        toggleBtn.click();
281	        assert.strictEqual(formWrapper.hidden, false, 'Form wrapper should be visible after toggle');
282	    } finally {
283	        cleanupContainers();
284	    }
285	});
286	
287	test('AC3 — Empty credentials list shows an empty-state message', async () => {
288	    // Override credentials list to return an empty object.
289	    const originalList    = api.config.credentials.list;
290	    api.config.credentials.list = async () => ({});
291	
292	    const container = await renderAndWait();
293	    try {
294	        const emptyMsg = container.querySelector('.credentials-table-container .empty-state');
295	        assert.ok(emptyMsg, 'Empty-state paragraph should appear when there are no credentials');
296	    } finally {
297	        api.config.credentials.list = originalList;
298	        cleanupContainers();
299	    }
300	});

101	
102	        try {
103	            await api.config.credentials.delete(host);
104	            showToast(`Credential for "${host}" deleted.`, 'success');
105	            onDeleted();
106	        } catch (err) {
107	            showToast(err.message || 'Failed to delete credential.', 'error');
108	            deleteBtn.disabled = false;
109	            deleteBtn.textContent = 'Delete';
110	        }
111	    });
112	
113	    return tr;
114	}
115	
116	// ---------------------------------------------------------------------------
117	// Credentials table rendering
118	// ---------------------------------------------------------------------------
119	
120	/**
121	 * Render a loading indicator into `tableContainer`.
122	 *
123	 * @param {HTMLElement} tableContainer
124	 */
125	function showLoading(tableContainer) {
126	    tableContainer.innerHTML = `
127	        <div class="loading-indicator" aria-live="polite" aria-label="Loading credentials…">
128	            <span class="spinner" aria-hidden="true"></span>
129	            <span>Loading credentials…</span>
130	        </div>
131	    `;
132	}
133	
134	/**
135	 * Fetch all credentials and render them into `tableContainer`.
136	 *
137	 * @param {HTMLElement} tableContainer
138	 */
139	async function renderCredentialsTable(tableContainer) {
140	    showLoading(tableContainer);
141	
142	    let credentials;
143	    try {
144	        credentials = await api.config.credentials.list();
145	    } catch (err) {
146	        clearElement(tableContainer);
147	        const errorP = document.createElement('p');
148	        errorP.className = 'error-message';
149	        errorP.setAttribute('role', 'alert');
150	        errorP.textContent = `Failed to load credentials: ${err.message || 'Unknown error'}`;
151	        tableContainer.appendChild(errorP);
152	        return;
153	    }
154	
155	    const entries = Object.entries(credentials || {});
156	
157	    if (entries.length === 0) {
158	        tableContainer.innerHTML = `
159	            <p class="empty-state">No credentials configured. Use the form below to add one.</p>
160	        `;
161	        return;
162	    }
163	
164	    const table = document.createElement('table');
165	    table.className = 'credentials-table';
166	    table.setAttribute('role', 'table');
167	    table.setAttribute('aria-label', 'Git credentials');
168	
169	    table.appendChild(buildTableHead());
170	
171	    const tbody = document.createElement('tbody');
172	
173	    for (const [host, maskedToken] of entries) {
174	        tbody.appendChild(buildCredentialRow(host, maskedToken, () => {
175	            renderCredentialsTable(tableContainer);
176	        }));
177	    }
178	
179	    table.appendChild(tbody);
180	    clearElement(tableContainer);
181	    tableContainer.appendChild(table);
182	}
183	
184	// ---------------------------------------------------------------------------
185	// Add / Update credential form
186	// ---------------------------------------------------------------------------
187	
188	/**
189	 * Build the "Add / Update Credential" section with a toggle button and inline form.
190	 *
191	 * @param {HTMLElement} tableContainer - Used to trigger a refresh after a successful save.
192	 * @returns {HTMLElement} The wrapper element containing the toggle button and form.
193	 */
194	function buildAddCredentialForm(tableContainer) {
195	    const section = document.createElement('div');
196	    section.className = 'add-credential-section';
197	
198	    const toggleBtn = document.createElement('button');
199	    toggleBtn.type = 'button';
200	    toggleBtn.className = 'btn btn-primary';
201	    toggleBtn.textContent = 'Add / Update Credential';
202	
203	    const formWrapper = document.createElement('div');
204	    formWrapper.className = 'form-wrapper';
205	    formWrapper.hidden = true;
206	
207	    const form = document.createElement('form');
208	    form.noValidate = true;
209	
210	    form.appendChild(createFormField('Host', 'text', 'host', {
211	        placeholder: 'e.g. github.com',
212	        required: true,
213	    }));
214	
215	    form.appendChild(createFormField('Token', 'password', 'token', {
216	        placeholder: 'Personal access token',
217	        required: true,
218	    }));
219	
220	    const actions = document.createElement('div');
221	    actions.className = 'form-actions';
222	
223	    const submitBtn = document.createElement('button');
224	    submitBtn.type = 'submit';
225	    submitBtn.className = 'btn btn-primary';
226	    submitBtn.textContent = 'Save';
227	
