688	/**
689	 * Render the Settings view into `container`.
690	 *
691	 * No cleanup function is returned because this view has no side-effects:
692	 * it does not start polling, install global event listeners, or hold any
693	 * external resources. The router does not need to call a teardown. This
694	 * is consistent with the `repositories` view, which follows the same pattern.
695	 *
696	 * @param {HTMLElement} container - The `#app` root element supplied by the router.
697	 * @param {Object}      _params   - Route params (none for this route).
698	 * @returns {void}
699	 */
700	export function renderSettings(container, _params) {

701	    document.title = 'Settings - ' + APP_NAME_SHORT;
702	    clearElement(container);
703	
704	    // Page heading
705	    const heading = document.createElement('h1');
706	    heading.textContent = 'Settings';
707	    container.appendChild(heading);
708	
709	    // Credentials section
710	    const credentials = buildCredentialsSection();
711	    container.appendChild(credentials.element);
712	
713	    // ---- Remaining sections ----
714	    const refreshDelay = buildRefreshDelaySection();
715	    container.appendChild(refreshDelay.element);
716	
717	    const webserverUrl = buildWebserverUrlSection();
718	    container.appendChild(webserverUrl.element);
719	
720	    const notesDisplay = buildNotesDisplaySection();
721	    container.appendChild(notesDisplay.element);
722	
723	    // ---- Form footer ----
724	    const footer = document.createElement('footer');
725	    footer.className = 'settings-footer';
726	
727	    const saveBtn = document.createElement('button');
728	    saveBtn.type = 'button';
729	    saveBtn.className = 'btn btn-primary';
730	    saveBtn.textContent = 'Save Settings';
731	    footer.appendChild(saveBtn);
732	    container.appendChild(footer);
733	
734	    saveBtn.addEventListener('click', async () => {
735	        saveBtn.disabled = true;
736	        saveBtn.textContent = 'Saving…';
737	
738	        try {
739	            const results = await Promise.all([
740	                refreshDelay.save(),
741	                webserverUrl.save(),
742	                notesDisplay.save(),
743	            ]);
744	
745	            if (results.every(Boolean)) {
746	                showToast('Settings saved.', 'success');
747	            }
748	        } finally {
749	            saveBtn.disabled = false;
750	            saveBtn.textContent = 'Save Settings';
751	        }
752	    });
753	}

